import 'package:flutter/material.dart';import 'package:myapp/models/measurement_model.dart';import 'package:myapp/repositories/measurement_repository.dart';class ProgressViewModel extends ChangeNotifier {  final MeasurementRepository _measurementRepository;  List<Measurement> _measurements = [];  ProgressViewModel(this._measurementRepository);  List<Measurement> get measurements => List.from(_measurements);  void loadMeasurements() {    _measurements = _measurementRepository.getMeasurements();    notifyListeners();  }  Future<void> addMeasurement(Measurement measurement) async {    await _measurementRepository.addMeasurement(measurement);    loadMeasurements();  }  Future<void> deleteMeasurement(int displayIndex) async {    final actualIndex = _measurements.length - 1 - displayIndex;    await _measurementRepository.deleteMeasurement(actualIndex);    loadMeasurements();  }  Future<void> clearMeasurements() async {    await _measurementRepository.clearMeasurements();    loadMeasurements();  }}